#!/usr/bin/env python3\n\"\"\"\n즉시 실행 가능한 간단한 테스트 스크립트\n현재 백엔드 상태와 영상 목록을 확인합니다.\n\"\"\"\n\nimport requests\nimport json\nimport os\nfrom pathlib import Path\n\ndef quick_test():\n    \"\"\"빠른 상태 확인\"\"\"\n    print(\"🔍 SafeFall 시스템 상태 확인\")\n    print(\"=\" * 40)\n    \n    # 1. 백엔드 서버 확인\n    try:\n        response = requests.get(\"http://localhost:5000\", timeout=3)\n        if response.status_code == 200:\n            print(\"✅ 백엔드 서버 실행 중\")\n        else:\n            print(f\"⚠️ 백엔드 응답 이상: {response.status_code}\")\n    except:\n        print(\"❌ 백엔드 서버가 실행되지 않았습니다!\")\n        print(\"   명령: cd E:\\\\safefall_backend\\\\back-end && python app.py\")\n        return False\n    \n    # 2. 파일시스템 영상 개수\n    try:\n        script_dir = Path(__file__).parent\n        videos_dir = script_dir / \"saved_videos\"\n        \n        if videos_dir.exists():\n            video_files = list(videos_dir.glob(\"*.mp4\")) + list(videos_dir.glob(\"*.avi\"))\n            print(f\"📁 파일시스템: {len(video_files)}개 영상\")\n            \n            # 최근 3개 파일\n            recent_files = sorted(video_files, key=lambda x: x.stat().st_mtime, reverse=True)[:3]\n            if recent_files:\n                print(\"   최신 파일:\")\n                for i, file in enumerate(recent_files, 1):\n                    print(f\"     {i}. {file.name}\")\n        else:\n            print(\"❌ saved_videos 디렉토리 없음\")\n            return False\n    except Exception as e:\n        print(f\"❌ 파일시스템 확인 실패: {e}\")\n    \n    # 3. API 영상 개수\n    try:\n        response = requests.get(\"http://localhost:5000/api/videos/saved\", timeout=5)\n        if response.status_code == 200:\n            data = response.json()\n            videos = data.get('videos', [])\n            print(f\"🌐 API 응답: {len(videos)}개 영상\")\n            \n            if len(videos) < len(video_files):\n                missing_count = len(video_files) - len(videos)\n                print(f\"⚠️ {missing_count}개 영상이 데이터베이스에 누락!\")\n                return \"needs_sync\"\n            else:\n                print(\"✅ 모든 영상이 동기화됨\")\n                return True\n        else:\n            print(f\"❌ API 오류: {response.status_code}\")\n            return False\n    except Exception as e:\n        print(f\"❌ API 테스트 실패: {e}\")\n        return False\n\ndef sync_now():\n    \"\"\"즉시 동기화 실행\"\"\"\n    print(\"\\n🔄 동기화 실행 중...\")\n    \n    try:\n        response = requests.post(\n            \"http://localhost:5000/api/videos/sync\",\n            headers={'Content-Type': 'application/json'},\n            timeout=30\n        )\n        \n        if response.status_code == 200:\n            data = response.json()\n            registered = data.get('registered', 0)\n            \n            if registered > 0:\n                print(f\"🎉 {registered}개 영상 등록 성공!\")\n                print(\"새로 등록된 영상:\")\n                for video in data.get('registered_videos', []):\n                    print(f\"  ✅ {video.get('filename')}\")\n            else:\n                print(\"ℹ️ 등록할 새 영상 없음\")\n            \n            return registered\n        else:\n            print(f\"❌ 동기화 실패: {response.status_code}\")\n            print(response.text)\n            return 0\n    except Exception as e:\n        print(f\"❌ 동기화 오류: {e}\")\n        return 0\n\ndef main():\n    result = quick_test()\n    \n    if result == \"needs_sync\":\n        print(\"\\n🔧 동기화 필요! 자동으로 동기화를 시작합니다...\")\n        registered = sync_now()\n        \n        if registered > 0:\n            print(f\"\\n✨ 완료! {registered}개 영상이 새로 등록되었습니다.\")\n            print(\"🌐 프론트엔드에서 '🔄 새 영상 찾기' 버튼을 클릭하세요.\")\n        else:\n            print(\"\\n❌ 동기화 중 문제가 발생했습니다.\")\n    elif result == True:\n        print(\"\\n✅ 모든 시스템이 정상 작동 중입니다!\")\n    else:\n        print(\"\\n❌ 시스템에 문제가 있습니다. 백엔드를 확인하세요.\")\n    \n    print(f\"\\n📊 최종 확인: http://localhost:5000/api/videos/saved\")\n    print(f\"🌐 프론트엔드: http://localhost:5173\")\n\nif __name__ == \"__main__\":\n    main()\n